import sys
import json

import pandas as pd


def main() -> None:
    text = sys.stdin.read()
    try:
        data = json.loads(text)
    except (json.JSONDecodeError, ValueError):
        print("Invalid JSON")
        return

    if not isinstance(data, list):
        print("Invalid JSON")
        return

    if not data:
        return

    columns = list(data[0].keys())
    df = pd.DataFrame(data, columns=columns, dtype=object)

    out = [",".join(str(c) for c in columns)]
    for row in df.itertuples(index=False, name=None):
        out.append(",".join(str(v) for v in row))
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

import sys
import pandas as pd
from lxml import etree

def main():
    data = sys.stdin.read()
    error_msg = "Error: XML structure does not match expected format."
    try:
        root = etree.fromstring(data.encode('utf-8'))
    except Exception:
        print(error_msg)
        return

    items = list(root.iter('item'))
    if not items:
        print(error_msg)
        return

    columns = [child.tag for child in items[0]]
    if not columns:
        print(error_msg)
        return

    rows = []
    for item in items:
        row = {}
        for child in item:
            row[child.tag] = child.text if child.text is not None else ''
        rows.append(row)

    try:
        df = pd.DataFrame(rows, columns=columns)
    except Exception:
        print(error_msg)
        return

    csv_output = df.to_csv(index=False, lineterminator='\n')
    sys.stdout.write(csv_output)

if __name__ == '__main__':
    main()

