import sys
import string

def main():
    data = sys.stdin.read()
    tokens = data.split()
    punct = set(string.punctuation)
    counts = {}
    order = []
    for tok in tokens:
        if not tok.startswith('$'):
            continue
        remainder = tok[1:]
        if len(remainder) == 0:
            continue
        if all(c in punct for c in remainder):
            continue
        if tok not in counts:
            counts[tok] = 0
            order.append(tok)
        counts[tok] += 1
    out_lines = []
    for w in order:
        out_lines.append(f"{w} {counts[w]}")
    if out_lines:
        print('\n'.join(out_lines))

if __name__ == '__main__':
    main()

