import sys
import regex
from collections import OrderedDict


def main():
    text = sys.stdin.read()
    tokens = text.split()
    counts = OrderedDict()
    punct_only_pattern = regex.compile(r'^[\p{P}\p{S}]+$')
    for tok in tokens:
        if tok.startswith('$'):
            rest = tok[1:]
            if rest == '':
                continue
            if punct_only_pattern.match(rest):
                continue
            counts[tok] = counts.get(tok, 0) + 1
    out_lines = []
    for word, cnt in counts.items():
        out_lines.append(f"{word} {cnt}")
    if out_lines:
        print("\n".join(out_lines))


if __name__ == '__main__':
    main()
